import { createSlice } from '@reduxjs/toolkit';

const initialState = 
{
  "categories": [
    {
      "id": "cspm-executive",
      "name": "CSPM Executive Dashboard",
      "widgets": [
        {
          "id": "cloud-accounts",
          "name": "Cloud Accounts",
          "text": "Connected (2) | Not Connected (2) | Total: 2 Accounts",
          "isVisible": true
        },
        {
          "id": "cloud-risk-assessment",
          "name": "Cloud Account Risk Assessment",
          "text": "Failed (1689) | Warning (681) | Not available (36) | Passed (7253) | Total: 9659",
          "isVisible": true
        }
      ]
    },
    {
      "id": "cwpp-dashboard",
      "name": "CWPP Dashboard", 
      "widgets": [
        {
          "id": "top-5-namespace-alerts",
          "name": "Top 5 Namespace Specific Alerts",
          "text": "No Graph data available!",
          "isVisible": true
        },
        {
          "id": "workload-alerts",
          "name": "Workload Alerts",
          "text": "No Graph data available!",
          "isVisible": true
        }
      ]
    },
    {
      "id": "registry-scan",
      "name": "Registry Scan",
      "widgets": [
        {
          "id": "image-risk-assessment",
          "name": "Image Risk Assessment",
          "text": "Critical (9) | High (150) | Total vulnerabilities: 1470",
          "isVisible": true
        },
        {
          "id": "image-security-issues",
          "name": "Image Security Issues", 
          "text": "Critical (2) | High (2) | Total images: 2",
          "isVisible": true
        }
      ]
    }
  ],
  "searchTerm": ""
};

const dashboardSlice = createSlice({
  name: 'dashboard',
  initialState,
  reducers: {
    addWidget: (state, action) => {
      const { categoryId, widget } = action.payload;
      const category = state.categories.find(cat => cat.id === categoryId);
      if (category) {
        const newWidget = {
          ...widget,
          id: `widget-${Date.now()}`,
          isVisible: true
        };
        category.widgets.push(newWidget);
      }
    },
    removeWidget: (state, action) => {
      const { categoryId, widgetId } = action.payload;
      const category = state.categories.find(cat => cat.id === categoryId);
      if (category) {
        category.widgets = category.widgets.filter(widget => widget.id !== widgetId);
      }
    },
    toggleWidgetVisibility: (state, action) => {
      const { categoryId, widgetId } = action.payload;
      const category = state.categories.find(cat => cat.id === categoryId);
      if (category) {
        const widget = category.widgets.find(w => w.id === widgetId);
        if (widget) {
          widget.isVisible = !widget.isVisible;
        }
      }
    },
    setSearchTerm: (state, action) => {
      state.searchTerm = action.payload;
    }
  }
});

export const { addWidget, removeWidget, toggleWidgetVisibility, setSearchTerm } = dashboardSlice.actions;
export default dashboardSlice.reducer;
